css:
* {
    font-family: "Times New Roman", Times, serif;
}

body {
    font-size: 14px;
    color: #111;
    margin: 30px;
}

h3 {
    font-size: 22px;
    text-align: left;
    color: #111;
    margin-bottom: 12px;
    letter-spacing: 0.2px;
}

h4 {
    font-size: 18px;
    margin-top: 32px;
    color: #111;
    font-weight: bold;
    padding-bottom: 5px;
    letter-spacing: 0.2px;
    border: none;
}

h5 {
    font-size: 16px;
    margin-top: 24px;
    color: #111;
    font-weight: bold;
    padding-bottom: 3px;
    border: none;
}

strong {
    color: #111;
    font-weight: 600;
}

/* Table Styling: Only vertical lines, horizontal line at header and footer of all tables except .report-table */
table, table th, table td {
    border-left: 1.5px solid #888;
    border-right: 1.5px solid #888;
    border-top: none !important;
    border-bottom: none !important;
    padding: 8px 10px;
    text-align: left;
    vertical-align: middle;
}
table th:first-child, table td:first-child {
    border-left: none;
}
table th:last-child, table td:last-child {
    border-right: none;
}
table th {
    font-size: 14px;
    font-weight: 700;
    color: #111;
    background: none;
    border-top: 2px solid #888 !important;
    border-bottom: 2px solid #888 !important;
}
table tr:last-child td {
    border-bottom: 2px solid #888 !important;
}
/* Remove horizontal lines for .report-table */
table.report-table, .report-table th, .report-table td {
    border-top: none !important;
    border-bottom: none !important;
}

ol {
    padding-left: 20px;
    margin-top: 10px;
}

hr {
    margin-top: 30px;
    margin-bottom: 20px;
    border: none;
    border-top: 1px solid #888;
}

.signature-table,
.place-date-table {
    width: 100%;
    font-size: 13px;
    margin-top: 40px;
}
.signature-table td {
    text-align: center;
    padding-top: 30px;
}
.place-date-table td {
    padding: 5px 0;
}

/* Section and Note Formatting */
.section-heading {
    font-size: 17px;
    color: #111;
    margin-top: 28px;
    margin-bottom: 8px;
    font-weight: 700;
    border: none;
    padding-left: 0;
    background: none;
}
.note-title {
    font-size: 15px;
    color: #111;
    font-weight: 600;
    margin-top: 14px;
    margin-bottom: 5px;
}
.note-desc {
    font-size: 13px;
    color: #222;
    margin-bottom: 7px;
    text-align: justify;
}

/* Print/PDF Friendly */
.page-break {
    page-break-before: always;
}
@media print {
    body {
        margin: 10mm 10mm 10mm 10mm;
    }
    .page-break {
        display: block;
        page-break-before: always;
    }
    table {
        page-break-inside: avoid;
    }
}
